() => {
  // Find elements containing "Market Data" text
  const allElements = document.querySelectorAll('*');
  const matches = [];
  for (const el of allElements) {
    const text = el.textContent || '';
    if (text.includes('Market Data') && el.children.length < 5) {
      const rect = el.getBoundingClientRect();
      matches.push({
        tag: el.tagName,
        text: text.substring(0, 200),
        top: rect.top,
        left: rect.left,
        visible: rect.top >= 0 && rect.top < window.innerHeight
      });
    }
  }
  return matches.slice(0, 20);
}

() => {
  // Find elements containing "Market" text
  const html = document.body.innerHTML;
  const matches = [];
  let idx = 0;
  while ((idx = html.indexOf('Market Data', idx)) !== -1) {
    matches.push(html.substring(Math.max(0, idx - 100), idx + 200));
    idx += 11;
    if (matches.length > 10) break;
  }
  return matches;
}

() => {
  // Get headings on the page
  const headings = document.querySelectorAll('h1, h2, h3, h4');
  const headingTexts = [];
  for (const h of headings) {
    headingTexts.push(h.textContent.trim());
  }
  return headingTexts.slice(0, 50);
}

() => {
  const text = document.body.innerText;
  const idx = text.indexOf('Market Data');
  if (idx === -1) return 'Not found';
  return text.substring(Math.max(0, idx - 200), idx + 500);
}

() => {
  const text = document.body.innerText;
  return {
    hasMarketData: text.includes('Market Data'),
    length: text.length,
    snippet: text.substring(0, 500)
  };
}

() => {
  const allText = document.body.innerText;
  const searchTerm = 'Market Data';
  const lower = allText.toLowerCase();
  const idx = lower.indexOf(searchTerm.toLowerCase());
  return { 
    found: idx !== -1, 
    index: idx,
    context: idx !== -1 ? allText.substring(Math.max(0, idx - 200), idx + 500) : '',
    length: allText.length
  };
}
